/**
 * Canonical Veryfront API transport for the conversations SDK, configured with one options
 * object.
 */
import { createCanonicalVeryfrontApiTransport, } from "../platform/adapters/veryfront-api-transport.js";
const NO_RETRY = { maxRetries: 0, initialDelay: 0, maxDelay: 0 };
/**
 * Create the canonical Veryfront API transport for the conversations SDK. It owns the
 * origin, credentials, retries, response body limits and telemetry of every SDK request.
 */
export function createConversationsApiTransport(options) {
    return createCanonicalVeryfrontApiTransport(options.baseUrl, options.getToken, options.retry ?? NO_RETRY, undefined, options.authMode);
}
